class Solution {
  public int minimumDistance(int[][] points) {
    int n = points.length;
    int[][] values = new int[2][n];
    for (int i = 0; i < n; i++) {
      values[0][i] = points[i][0] + points[i][1];
      values[1][i] = points[i][0] - points[i][1];
    }
    int[][] max1 = new int[2][2], max2 = new int[2][2];
    int[][] min1 = new int[2][2], min2 = new int[2][2];
    for (int type = 0; type < 2; type++) {
      max1[type][0] = max2[type][0] = Integer.MIN_VALUE;
      min1[type][0] = min2[type][0] = Integer.MAX_VALUE;
      for (int i = 0; i < n; i++) {
        int v = values[type][i];
        if (v > max1[type][0]) {
          max2[type] = max1[type].clone();
          max1[type] = new int[] {v, i};
        } else if (v > max2[type][0]) max2[type] = new int[] {v, i};
        if (v < min1[type][0]) {
          min2[type] = min1[type].clone();
          min1[type] = new int[] {v, i};
        } else if (v < min2[type][0]) min2[type] = new int[] {v, i};
      }
    }
    int answer = Integer.MAX_VALUE;
    for (int removed = 0; removed < n; removed++) {
      int maxSum = max1[0][1] == removed ? max2[0][0] : max1[0][0];
      int minSum = min1[0][1] == removed ? min2[0][0] : min1[0][0];
      int maxDiff = max1[1][1] == removed ? max2[1][0] : max1[1][0];
      int minDiff = min1[1][1] == removed ? min2[1][0] : min1[1][0];
      answer = Math.min(answer, Math.max(maxSum - minSum, maxDiff - minDiff));
    }
    return answer;
  }
}
